package esercizi_3;

public class es_1 {

	public static void main(String[] args) {
		// TODO Auto-generated method stub

		/*
		 * Calcolare la somma dei numeri da 1 a 220 utilizzando un ciclo "for".
		 */
		
		int numeroFinale = 0;
		
		for(int i = 0; i <= 220; i++)
		{
			numeroFinale = numeroFinale + i;
		}
		
		System.out.println("La somma dei numeri da 1 a 220 è: " + numeroFinale);
	}
/*
 * voto 9/10
 */
}
